FACT_FIX={'возраст считают на дату вылета':'возраст считают на дату каждого перелёта: если до обратного рейса исполнится 2 года, назад нужно отдельное место'}
TRIG_FIX={'щен':['щенок','щенк'],'поезд':['на поезде','поездом','ж/д','железнодорож','поезда']}
TRIG_ID_FIX={('support-communication-privacy','собак'):['поводыр','собака-проводник','собакой-проводник']}
TRIG_ADD={'on-trip-hotel-problems':['грязн','не убира','тарака','не соответству','жалоб','переселит','уже в отеле','заселение']}
def apply(path,out):
    d=json.load(open(path,encoding='utf-8'))
    used=set()
    for t in d:
        for k in ('ask','advise','operator','avoid'):
            new=[]
            for x in t[k]:
                hit=None
                for (i,f,sub),rep in EDITS.items():
                    if i==t['id'] and f==k and x.startswith(sub): hit=(i,f,sub); break
                if hit:
                    used.add(hit)
                    if EDITS[hit] is not None: new.append(EDITS[hit])
                else: new.append(x)
            t[k]=new
        for f in t.get('facts',[]):
            for a,b in FACT_FIX.items():
                if a in f.get('text',''): f['text']=f['text'].replace(a,b)
        tr=[]
        for x in t['triggers']: tr+=TRIG_ID_FIX.get((t['id'],x.lower()), TRIG_FIX.get(x.lower(),[x]))
        t['triggers']=tr+[x for x in TRIG_ADD.get(t['id'],[]) if x not in tr]
    json.dump(d,open(out,'w',encoding='utf-8'),ensure_ascii=False,indent=1)
    return used
used=set()
for g in sys.argv[1:]:
    used|=apply(f'group{g}_playbook.json',f'/home/claude/totus_ai_v2/docs/playbook/group{g}.json')
missing=[k for k in EDITS if k not in used and any(True for _ in [0])]
print('edits applied',len(used),'of',len(EDITS))
